python3 -c import pathlib,json; rows=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try: rows.append({'pid':p.name,'cmd':(p/'cmdline').read_bytes().decode(errors='replace').replace(chr(0),' '),'status':(p/'status').read_text()})
 except (FileNotFoundError,PermissionError):pass
print(json.dumps(rows))
